function deleteDuplicates(head) {
  if (head === null) return null;
  const seen = new Set([head.val]);
  let prev = head;
  while (prev.next !== null) {
    if (seen.has(prev.next.val)) {
      prev.next = prev.next.next;   // seen before: unlink it
    } else {
      seen.add(prev.next.val);
      prev = prev.next;
    }
  }
  return head;
}

